import { ASTROVIP_HOUSE_SYSTEM, validateHouseResult } from './swiss-adapter.js';

/**
 * Benchmark validator for Swiss Ephemeris / Koch fixtures.
 * Expected numeric values must be generated by Swiss Ephemeris (swetest),
 * never copied from AstroVip's legacy JS angle formulas.
 */
export function angularDistance(a,b){
  const x=Math.abs((((Number(a)-Number(b))+540)%360)-180);
  return x;
}

export function benchmarkKoch(actual, expected, toleranceDeg=1/3600){
  validateHouseResult(actual);
  if(!expected || expected.houseSystem!==ASTROVIP_HOUSE_SYSTEM)
    throw new Error('Benchmark fixture must explicitly use Koch (K).');
  if(!Array.isArray(expected.cusps)||expected.cusps.length!==12)
    throw new Error('Benchmark fixture must contain 12 reference cusps.');

  const checks=[];
  actual.cusps.forEach((v,i)=>checks.push({
    field:`cusp${i+1}`,
    errorDeg:angularDistance(v,expected.cusps[i])
  }));
  for(const k of ['asc','mc','dsc','ic']){
    checks.push({field:k,errorDeg:angularDistance(actual.axes[k],expected.axes[k])});
  }
  const failed=checks.filter(x=>x.errorDeg>toleranceDeg);
  return {ok:failed.length===0,toleranceDeg,checks,failed};
}

export const BENCHMARK_POLICY=Object.freeze({
  source:'Swiss Ephemeris swetest',
  houseSystem:'K',
  zodiac:'tropical',
  toleranceDeg:1/3600,
  legacyFormulaAsGroundTruth:false
});
